                        + "{\"segmentId\":\"s1\",\"sourceText\":\"b\"}]}");
        assertThat(dupSegment.status()).isEqualTo(422);
    }

    @Test
    @DisplayName("增加段落：草稿版本加一；重复 segmentId 返回 409")
