    void submitTranslation() throws Exception {
        long docId = createDocument(newRequestId(), "[\"en\"]",
                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
        ApiResult ok = submitTranslation(docId, "s1", "en", "alice", "hello", 1, newRequestId());
