        submitCategory(docId, "s1", "zh", "other", "alice", "{count} 个文件", 1, newRequestId());
        submitCategory(docId, "s1", "en", "one", "alice", "one file", 1, newRequestId());
        approveCategory(docId, "s1", "zh", "other", "bob", 1, newRequestId());
